input.content:
package bookstore

// Cost calculates the total cost, in cents, of a basket of books from the
// five-book series, applying as large a discount as possible.
//
// Each title is identified by an integer from 1 to 5. A group of distinct
// titles is priced at 800 per book, discounted by 5%, 10%, 20% or 25% for
// groups of 2, 3, 4 or 5 books respectively.
func Cost(books []int) int {
	// Count the copies of each title.
	counts := [5]int{}
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}

	// The basket can be viewed as shelves: shelf k holds one copy of every
	// title that has at least k copies. Each shelf is a group of distinct
	// titles, and this top-down grouping is optimal apart from one
	// refinement below.
	groups := [5]int{} // number of groups of each size (1..5)
	for k := 1; ; k++ {
		size := 0
		for _, c := range counts {
			if c >= k {
				size++
			}
		}
		if size == 0 {
			break
		}
		groups[size-1]++
	}

	// A group of five plus a group of three costs 3000 + 2160 = 5160,
	// whereas two groups of four cost 2 * 2560 = 5120. Whenever both a
	// five-group and a three-group exist, split the five-group into a
	// four-group and a single, and merge the single with the three-group
	// to form a second four-group.
	for groups[4] > 0 && groups[2] > 0 {
		groups[4]--
		groups[2]--
		groups[3] += 2
	}

	// Group prices in cents: 800, 1520, 2160, 2560, 3000.
	prices := [5]int{800, 1520, 2160, 2560, 3000}
	total := 0
	for i, n := range groups {
		total += n * prices[i]
	}
	return total
}

